import java.awt.*;import java.awt.image.*;import java.io.*;import java.util.*;import javax.imageio.ImageIO;import com.koios.client.arpg.*;import com.koios.client.graphic.*;
/** Expansion illustration source cells must remain distinct and resolve through the real art hook. */
public final class ExpansionIconsCheck {
 static int checks;static void check(boolean v,String text){checks++;if(!v)throw new AssertionError(text);}
 public static void main(String[] args)throws Exception{int[] ids={22430,22431,22432,22435,22436,22437,22438,22439};Set<Integer> hashes=new HashSet<>();com.koios.client.graphic.ImageProducer surface=new com.koios.client.graphic.ImageProducer(384,120);Arrays.fill(surface.canvasRaster,0x141B22);for(int i=0;i<ids.length;i++){Sprite s=ExpansionIcons.icon(ids[i]);check(s!=null&&ArtSprites.icon(ids[i])==s,"Actual art hook chooses expansion illustration "+ids[i]);check(s.myWidth==32&&s.myHeight==32&&s.highResolutionArt!=null&&s.highResolutionArt.getWidth()==128,"Inventory and retained source size "+ids[i]);int visible=0;for(int c:s.myPixels)if(c!=0)visible++;check(visible>60&&visible<900,"Readable transparent silhouette "+ids[i]+" pixels="+visible);check(hashes.add(Arrays.hashCode(s.myPixels)),"Distinct illustration "+ids[i]);s.drawSprite(12+i*46,18);}
 BufferedImage crisp=HighDpiArtCheck.present(surface,2),normal=HighDpiArtCheck.present(surface,1);int changes=0;for(int y=0;y<240;y++)for(int x=0;x<768;x++)if(crisp.getRGB(x,y)!=normal.getRGB(x/2,y/2))changes++;check(changes>500,"Actual2x composite retains source detail");BufferedImage preview=new BufferedImage(800,420,BufferedImage.TYPE_INT_RGB);Graphics2D g=preview.createGraphics();g.setColor(new Color(0x141B22));g.fillRect(0,0,800,420);g.setColor(new Color(0xD4BB87));g.setFont(new Font("SansSerif",Font.PLAIN,13));g.drawString("Actual inventory32px",12,20);g.drawImage(normal,8,25,null);g.drawString("Actual device-resolution2x",12,165);g.drawImage(crisp,8,180,null);for(int i=0;i<ids.length;i++)g.drawString(Integer.toString(ids[i]),20+i*92,390);g.dispose();ImageIO.write(preview,"png",new File("build/expansion-icons.png"));System.out.println("Passed "+checks+" expansion source-art, distinct silhouette and actual HiDPI checks.");}
}
